bounded_host_request.command:
set -eu
test "$(git rev-parse HEAD)" = "4b06a39ebdb8a99d5544b27c8a52f33ad8e42440"
git fetch --no-tags origin "refs/heads/fix/debugai-scout-diagnosis-handoff-20261016"
test "$(git rev-parse FETCH_HEAD)" = "681b9c74e79ac9cc309a1f5d0c8bdf67596f2112"
git merge-base --is-ancestor "4b06a39ebdb8a99d5544b27c8a52f33ad8e42440" "681b9c74e79ac9cc309a1f5d0c8bdf67596f2112"
python3 -B - <<'PY'
import subprocess,json
head="681b9c74e79ac9cc309a1f5d0c8bdf67596f2112"
paths=["orchestrator/source-scope.js","server/control/repository-snapshot.js","server/control/sandbox-runtime.js"]
src={p:subprocess.check_output(["git","show",head+":"+p],text=True) for p in paths}
node=r'''
const fs=require("node:fs"),path=require("node:path"),Module=require("node:module");
const src=JSON.parse(fs.readFileSync(0,"utf8")),loaded={};
function load(rel){
 if(loaded[rel])return loaded[rel];
 const file="/app/"+rel,m=new Module(file,module);
 m.filename=file;m.paths=Module._nodeModulePaths(path.dirname(file));
 const requireOriginal=m.require.bind(m);
 m.require=(name)=>name==="../../orchestrator/source-scope.js"?load("orchestrator/source-scope.js"):requireOriginal(name);
 m._compile(src[rel],file);
 return loaded[rel]=m.exports;
}
const {RepoPolicy}=require("/app/server/repo-policy.js");
const repo=new RepoPolicy().assertRepo("/workspace/debug-ai");
const report=(label,e)=>{const c=e.cause||e,msg=String(c.message||"");console.log(label+" "+JSON.stringify({code:String(e.message||"").split(":")[0],cause_code:c.code||null,cause_kind:msg.split(":")[0].slice(0,100)}));};
try{const x=load("server/control/repository-snapshot.js").repositorySnapshotId(repo,{allowMissingGitMarker:true});console.log("CANDIDATE_SNAPSHOT=PASS "+x.split("_")[0]);}
catch(e){report("CANDIDATE_SNAPSHOT=FAIL",e);process.exitCode=4;}
try{const m=load("server/control/sandbox-runtime.js").snapshotInventory(repo,{requiredPaths:["package.json","server/http.js"]});console.log("CANDIDATE_SANDBOX_INVENTORY=PASS "+JSON.stringify({files:m.files,bytes:m.bytes,excluded_parent:m.exclusions.filter(e=>[".worktrees",".verification"].includes(e.path)).map(e=>e.path),completeness:m.completeness}));}
catch(e){report("CANDIDATE_SANDBOX_INVENTORY=FAIL",e);process.exitCode=5;}
'''
subprocess.run(["docker","exec","-i","-w","/app","debug-ai-debug-ai-1","node","-e",node],input=json.dumps(src),text=True,check=True)
PY
test "$(git rev-parse HEAD)" = "4b06a39ebdb8a99d5544b27c8a52f33ad8e42440"
printf 'RUNNING_SOURCE_UNCHANGED=PASS\n'
